-- '채용공고 AI 파싱 신뢰성 개선 — NVIDIA NIM 동시성과 추론모델 사고과정 유출 잡기' 스터디를
-- 새로 만든다. 페이지 텍스트 수집(SPA/iframe/AJAX)을 다루는 기존 헤드리스 브라우저 스터디
-- (slug: headless-browser-spa-job-posting-scraping)와 같은 기능(JobApplicationUrlParseService)의
-- 후속처럼 보이지만, 이번엔 페이지를 가져온 이후 AI 응답 처리 단계의 문제라 계층이 달라 별도
-- 스터디로 분리하고 서로 RELATED로만 연결한다. content_markdown 값은 이스케이프 문제를
-- 원천 차단하기 위해 16진 리터럴(X'...')로 기록한다 (V102~V122 컨벤션 준용).

INSERT INTO `study` (`slug`, `title`, `summary`, `content_markdown`, `status`, `category_id`, `learned_at`, `published_at`, `created_at`, `updated_at`)
VALUES (
  'job-posting-ai-json-reliability',
  '채용공고 AI 파싱 신뢰성 개선 — NVIDIA NIM 동시성과 추론모델 사고과정 유출 잡기',
  '페이지 텍스트는 정상 수집됐는데도 다중 URL 수집 시 절반 가까이 "AI가 올바른 JSON을 반환하지 않았습니다"로 실패하던 문제를, NVIDIA API 동시 요청 한도(503 ResourceExhausted)·reasoning 모델의 사고 과정 유출·한글 토크나이저 비효율이라는 세 가지 원인으로 하나씩 좁혀가며 해결한 과정과, 같은 재발 방지책을 NvidiaNimClient/AiJsonSupport 공통 모듈로 추출한 리팩터링을 정리합니다.',
  X'',
  'PUBLISHED',
  6,
  '2026-08-02',
  NOW(),
  NOW(), NOW()
);
SET @study_id = LAST_INSERT_ID();

INSERT INTO `study_tag` (`study_id`, `tag_id`) SELECT @study_id, `id` FROM `tag` WHERE `name` IN ('AI', 'Spring AI', '동시성');
INSERT INTO `study_skill` (`study_id`, `skill_id`) VALUES (@study_id, 1), (@study_id, 5), (@study_id, 38);

SELECT `id` INTO @headless_browser_study_id FROM `study` WHERE `slug` = 'headless-browser-spa-job-posting-scraping';
INSERT INTO `study_relation` (`source_study_id`, `target_study_id`, `relation_type`, `display_order`) VALUES
  (@study_id, @headless_browser_study_id, 'RELATED', 0),
  (@headless_browser_study_id, @study_id, 'RELATED', 1);

INSERT INTO `experience_detail` (`experience_id`, `content`, `display_order`, `outcome`, `visible`)
SELECT `id`, '채용 공고 AI 파싱 안정화 — NVIDIA NIM 동시성/추론모델 응답 신뢰성 개선', 7,
       'NVIDIA API 동시 요청 한도(503 ResourceExhausted), reasoning 모델의 사고 과정 유출, 한글 토크나이저 비효율이 겹쳐 다중 URL 수집 시 절반 가까이 실패하던 문제를 진단하고, 세마포어 동시성 제한·detailed thinking off·출력 토큰 상한 조정으로 해결했습니다. 이어서 같은 재발 방지책이 다른 AI 호출 서비스에서도 필요하다는 것을 확인하고 NvidiaNimClient/AiJsonSupport 공통 모듈로 추출했습니다.',
       1
FROM `experience` WHERE `title` = '개인 풀스택 포트폴리오 플랫폼 구축 (Self-Intro)';
SET @detail_id = LAST_INSERT_ID();

INSERT INTO `experience_detail_skill` (`experience_detail_id`, `skill_id`, `list_order`)
SELECT @detail_id, `id`, ROW_NUMBER() OVER (ORDER BY `id`) - 1
FROM `skill` WHERE `name` IN ('Java', 'Spring Boot', 'LLM');

INSERT INTO `study_experience_detail` (`study_id`, `experience_detail_id`)
VALUES (@study_id, @detail_id);
